use super::*;
use std::os::unix::fs::symlink;
struct Fixture{root:PathBuf,docs:PathBuf}
impl Fixture{
 fn new()->Self{let root=std::env::temp_dir().join(format!("peggle-owned-save-test-{}",id()));fs::create_dir(&root).unwrap();let docs=root.join("Documents");fs::create_dir(&docs).unwrap();Self{root,docs}}
 fn game(&self)->PathBuf{Manager::guest(&self.docs)}
 fn seed(&self){let g=self.game();fs::create_dir_all(g.join("Documents/userdata/replays")).unwrap();for(p,b)in data(){fs::write(g.join("Documents").join(p),b).unwrap();}fs::write(g.join("Documents/userdata/game_center.dat"),b"OWNED-ACCOUNT-TOKEN-NOT-EXPORTED").unwrap();fs::create_dir_all(g.join("Library/Preferences")).unwrap();let mut p=plist::Dictionary::new();p.insert("CurUser".into(),plist::Value::String("Second".into()));p.insert("SDKAccountToken".into(),plist::Value::String("OWNED-SECRET".into()));p.insert("store.nights.unlock".into(),plist::Value::Boolean(true));plist::Value::Dictionary(p).to_file_xml(g.join("Library/Preferences").join(format!("{GAME}.plist"))).unwrap();fs::write(self.docs.join("Peggle-C49-runtime.conf"),b"owned-host-settings").unwrap();}
}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
fn data()->BTreeMap<String,Vec<u8>>{
 let mut index=Vec::from(1u32.to_le_bytes());index.extend_from_slice(&2u16.to_le_bytes());for(name,seq,file)in[("Owned Player",1u32,1u32),("Second",2,7)]{index.extend_from_slice(&(name.len()as u16).to_le_bytes());index.extend_from_slice(name.as_bytes());index.extend_from_slice(&seq.to_le_bytes());index.extend_from_slice(&file.to_le_bytes());}
 let mut d=vec![0x42;512];d[..4].copy_from_slice(&25u32.to_le_bytes());BTreeMap::from([("userdata/users.dat".into(),index),("userdata/user1.dat".into(),d.clone()),("userdata/user7.dat".into(),d),("userdata/stage7.sav".into(),b"owned-suspended-board".to_vec()),("userdata/replays/Replay0.peg".into(),b"owned-opaque-replay".to_vec()),("userdata/highscores.dat".into(),b"owned-highscores".to_vec())])
}
fn manifest(files:&BTreeMap<String,Vec<u8>>)->Value{json!({"format":"PeggleHDSave","schema":1,"game":GAME,"version":GAME_VERSION,"original_ipa_sha256":GAME_SHA,"account_state_policy":"excluded","game_center_file_excluded":true,"selected_profile_id":7,"files":files.iter().map(|(p,b)|json!({"path":p,"bytes":b.len(),"sha256":hash(b)})).collect::<Vec<_>>()})}
fn archive(path:&Path,files:&BTreeMap<String,Vec<u8>>,m:Option<&Value>,extra:&[(String,Vec<u8>,bool)]){
 let f=File::create(path).unwrap();let mut z=zip::ZipWriter::new(f);let opt=zip::write::FileOptions::default().compression_method(zip::CompressionMethod::Deflated).unix_permissions(0o600);
 if let Some(m)=m{z.start_file("manifest.json",opt).unwrap();z.write_all(&serde_json::to_vec(m).unwrap()).unwrap();}
 for(p,b)in files{z.start_file(p,opt).unwrap();z.write_all(b).unwrap();}
 for(p,b,link)in extra{if *link{z.add_symlink(p,"/owned-outside-target",opt).unwrap();}else{z.start_file(p,opt).unwrap();z.write_all(b).unwrap();}}
 z.finish().unwrap();
}
fn snapshot(root:&Path)->BTreeMap<String,String>{fn walk(root:&Path,p:&Path,out:&mut BTreeMap<String,String>){if !p.exists(){return;}for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){out.insert(format!("{}/",p.strip_prefix(root).unwrap().display()),"dir".into());walk(root,&p,out);}else{out.insert(p.strip_prefix(root).unwrap().to_str().unwrap().into(),hash(&fs::read(p).unwrap()));}}}let mut out=BTreeMap::new();walk(root,root,&mut out);out}
#[test]fn public_SHA256_matches_known_vectors(){assert_eq!(hash(b""),"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");assert_eq!(hash(b"abc"),"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");}
#[test]fn export_is_game_only_and_validation_is_nonmutating(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let before=snapshot(&f.game());let out=m.export().unwrap();assert_eq!(snapshot(&f.game()),before);let all=snapshot(&f.root);let preview=m.validate(&out).unwrap();assert_eq!(preview.profiles,2);assert_eq!(preview.files,6);assert_eq!(preview.selected_id,7);assert_eq!(snapshot(&f.root),all);let(files,selected,_)=m.parse_archive(&out).unwrap();assert_eq!(files,data());assert_eq!(selected,7);assert!(files.keys().all(|p|!p.contains("game_center")&&!p.contains("Preferences")&&!p.contains("runtime")));}
#[test]fn exact_restore_retains_previous_and_creates_only_minimal_selected_profile_preference(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let old=snapshot(&f.game());let out=m.export().unwrap();let p=m.validate(&out).unwrap();assert!(m.restore(&p.token,false).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");m.restore(&p.token,true).unwrap();let state=m.state().unwrap();assert_eq!(state["previous"],"legacy");assert_eq!(state["generation"],1);assert_ne!(state["active"],"legacy");assert_eq!(snapshot(&f.game()),old);let g=m.active_guest(&state).unwrap();let(files,selected,excluded)=m.collect(&g).unwrap();assert_eq!(files,data());assert_eq!(selected,7);assert!(!excluded);let pref=plist::Value::from_file(g.join("Library/Preferences").join(format!("{GAME}.plist"))).unwrap();assert_eq!(pref.as_dictionary().unwrap().len(),1);assert_eq!(pref.as_dictionary().unwrap()["CurUser"].as_string(),Some("Second"));assert!(!g.join("Documents/userdata/game_center.dat").exists());}
#[test]fn interrupted_stages_never_replace_active_data_and_remain_unselected_after_reopen(){for fail in 1..=3{let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let old=snapshot(&f.game());let state=m.state().unwrap();let out=m.export().unwrap();let p=m.validate(&out).unwrap();assert!(m.restore_inner(&p.token,true,fail).is_err());assert_eq!(m.state().unwrap(),state);assert_eq!(snapshot(&f.game()),old);drop(m);let m=Manager::open(&f.docs).unwrap();assert_eq!(m.state().unwrap()["active"],"legacy");assert_eq!(m.active_guest(&m.state().unwrap()).unwrap(),fs::canonicalize(f.game()).unwrap());}}
#[test]fn rollback_is_confirmed_verified_and_reversible_without_deleting_either_slot(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let old=snapshot(&f.game());let a=m.export().unwrap();let p=m.validate(&a).unwrap();m.restore(&p.token,true).unwrap();let new_slot=m.state().unwrap()["active"].as_str().unwrap().to_owned();let new_root=m.data_root(&new_slot).unwrap();assert!(m.can_rollback().unwrap());assert!(m.rollback(false).is_err());m.rollback(true).unwrap();assert_eq!(m.state().unwrap()["active"],"legacy");assert_eq!(snapshot(&f.game()),old);assert!(new_root.exists());m.rollback(true).unwrap();assert_eq!(m.state().unwrap()["active"],new_slot);assert_eq!(snapshot(&f.game()),old);}
#[test]fn rollback_detects_tampered_previous_data_without_changing_selection(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let a=m.export().unwrap();let p=m.validate(&a).unwrap();m.restore(&p.token,true).unwrap();let old=m.state().unwrap();fs::write(f.game().join("Documents/userdata/stage7.sav"),b"owned-external-tamper").unwrap();assert!(m.rollback(true).is_err());assert_eq!(m.state().unwrap(),old);}
#[test]fn confirmation_is_bound_to_exact_validated_bytes_and_current_generation(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let a=m.export().unwrap();let first=m.validate(&a).unwrap();let second=m.validate(&a).unwrap();assert!(m.restore(&first.token,true).is_err());fs::write(&a,b"owned-changed-source-after-validation").unwrap();m.restore(&second.token,true).unwrap();assert_eq!(m.collect(&m.active_guest(&m.state().unwrap()).unwrap()).unwrap().0,data());let a=m.export().unwrap();let p=m.validate(&a).unwrap();let state=m.state().unwrap();let mut changed=state.clone();changed["generation"]=json!(99);fs::write(m.base.join("state.json"),serde_json::to_vec(&changed).unwrap()).unwrap();assert!(m.restore(&p.token,true).is_err());assert_eq!(m.state().unwrap(),changed);}
#[test]fn game_lease_blocks_all_new_save_manager_access_until_process_session_ends(){let f=Fixture::new();f.seed();let m=Manager::open(&f.docs).unwrap();assert!(Manager::open(&f.docs).is_err());let lease=m.begin_game().unwrap();assert_eq!(lease.data_root,fs::canonicalize(&f.docs).unwrap());assert!(Manager::open(&f.docs).is_err());drop(lease);assert!(Manager::open(&f.docs).is_ok());}
#[test]fn traversal_absolute_links_duplicate_case_and_foreign_members_are_rejected(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let d=data();let mf=manifest(&d);let mut count=0;for name in ["../escape","/userdata/users.dat","userdata/../escape","userdata\\user1.dat","userdata//user1.dat","C:/userdata/user1.dat","userdata/users.dat","USERDATA/USERS.DAT","userdata/./user1.dat","Library/Preferences/token.plist","userdata/game_center.dat","payload.ipa"]{let p=f.root.join(format!("bad{count}.zip"));archive(&p,&d,Some(&mf),&[(name.into(),b"owned-bad".to_vec(),false)]);assert!(m.validate(&p).is_err(),"{name}");count+=1;}let p=f.root.join("link.zip");archive(&p,&d,Some(&mf),&[("userdata/stat_link.dat".into(),vec![],true)]);assert!(m.validate(&p).is_err());assert!(!f.root.join("escape").exists());println!("C49_ARCHIVE_PATHS rejected={count}+link no_extraction_or_publication=true");}
#[test]fn missing_manifest_foreign_game_versions_and_account_policy_are_rejected(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let d=data();let p=f.root.join("bad.zip");archive(&p,&d,None,&[]);assert!(m.validate(&p).is_err());for(key,value)in[("game",json!("com.popcap.ios.Peggle")),("version",json!("1.7.2")),("schema",json!(2)),("original_ipa_sha256",json!("foreign")),("account_state_policy",json!("include"))]{let mut mf=manifest(&d);mf[key]=value;archive(&p,&d,Some(&mf),&[]);assert!(m.validate(&p).is_err(),"{key}");}}
#[test]fn bad_hash_lengths_duplicate_manifest_missing_unlisted_files_are_rejected(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let d=data();let p=f.root.join("bad.zip");for kind in 0..5{let mut mf=manifest(&d);match kind{0=>mf["files"][0]["sha256"]=json!("00"),1=>mf["files"][0]["bytes"]=json!(999999),2=>{let x=mf["files"][0].clone();mf["files"].as_array_mut().unwrap().push(x);},3=>{mf["files"].as_array_mut().unwrap().pop();},4=>mf["selected_profile_id"]=json!(999),_=>unreachable!()};archive(&p,&d,Some(&mf),&[]);assert!(m.validate(&p).is_err(),"kind{kind}");}}
#[test]fn malformed_profile_index_and_details_fail_even_with_matching_archive_hashes(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let p=f.root.join("bad.zip");for kind in 0..7{let mut d=data();match kind{0=>{d.get_mut("userdata/users.dat").unwrap().truncate(5);},1=>{d.get_mut("userdata/users.dat").unwrap()[0]=2;},2=>{d.remove("userdata/user7.dat");},3=>{d.get_mut("userdata/user1.dat").unwrap()[0]=24;},4=>{d.get_mut("userdata/user7.dat").unwrap().truncate(493);},5=>{d.insert("userdata/user99.dat".into(),d["userdata/user1.dat"].clone());},6=>{d.get_mut("userdata/users.dat").unwrap().push(0);},_=>unreachable!()};let mf=manifest(&d);archive(&p,&d,Some(&mf),&[]);assert!(m.validate(&p).is_err(),"kind{kind}");}}
#[test]fn source_file_and_state_symlinks_are_refused(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let a=m.export().unwrap();let link=f.root.join("archive-link.zip");symlink(&a,&link).unwrap();assert!(m.validate(&link).is_err());let bad=f.game().join("Documents/userdata/stat_link.dat");symlink(&a,&bad).unwrap();assert!(m.export().is_err());fs::remove_file(bad).unwrap();let state=f.root.join("owned-state.json");fs::write(&state,b"{}").unwrap();symlink(&state,m.base.join("state.json")).unwrap();assert!(m.state().is_err());}
#[test]fn oversized_member_metadata_and_file_count_are_refused_without_publishing(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let p=f.root.join("large.zip");let d=data();let mf=manifest(&d);archive(&p,&d,Some(&mf),&[("userdata/stat_big.dat".into(),vec![0;MAX_FILE as usize+1],false)]);assert!(m.validate(&p).is_err());let extras:Vec<_>=(0..MAX_FILES+1).map(|n|(format!("userdata/stat_{n}.dat"),Vec::new(),false)).collect();archive(&p,&BTreeMap::new(),Some(&mf),&extras);assert!(m.validate(&p).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");}

#[test]fn total_expanded_archive_limit_is_separate_from_manifest_allowance(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let mut d=data();for i in 0..9{d.insert(format!("userdata/stat_large{i}.dat"),vec![0;MAX_FILE as usize]);}let p=f.root.join("expanded-too-large.zip");archive(&p,&d,Some(&manifest(&d)),&[]);let error=m.validate(&p).unwrap_err();assert!(error.contains("total size"),"{error}");assert_eq!(m.state().unwrap()["active"],"legacy");}
#[test]fn incomplete_or_symlinked_slots_and_corrupt_state_do_not_start_the_game(){let f=Fixture::new();let m=Manager::open(&f.docs).unwrap();let key=id();let slot=m.base.join("slots").join(&key);fs::create_dir(&slot).unwrap();let state=json!({"schema":1,"generation":1,"active":key,"previous":null,"recovery":null});fs::write(m.base.join("state.json"),serde_json::to_vec(&state).unwrap()).unwrap();assert!(m.state().is_err());fs::remove_file(m.base.join("state.json")).unwrap();fs::write(m.base.join("state.json"),b"owned-corrupt-state").unwrap();assert!(m.begin_game().is_err());}

#[test]fn invalid_zip_edited_duplicate_JSON_and_directory_members_fail_closed(){let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let p=f.root.join("bad.zip");fs::write(&p,b"owned-not-a-zip").unwrap();assert!(m.validate(&p).is_err());let d=data();let mf=manifest(&d);archive(&p,&d,Some(&mf),&[("userdata/".into(),vec![],false)]);assert!(m.validate(&p).is_err());for raw in [serde_json::to_string_pretty(&mf).unwrap(),format!("{{\"schema\":1,{}",&serde_json::to_string(&mf).unwrap()[1..])]{let file=File::create(&p).unwrap();let mut z=zip::ZipWriter::new(file);let options=zip::write::FileOptions::default();z.start_file("manifest.json",options).unwrap();z.write_all(raw.as_bytes()).unwrap();for(p,b)in &d{z.start_file(p,options).unwrap();z.write_all(b).unwrap();}z.finish().unwrap();assert!(m.validate(&p).is_err());}assert_eq!(m.state().unwrap()["active"],"legacy");}
#[test]fn unsafe_guest_root_and_excessively_nested_recovery_never_start_or_replace_game(){let f=Fixture::new();let m=Manager::open(&f.docs).unwrap();let outside=f.root.join("owned-outside");fs::create_dir(&outside).unwrap();symlink(outside,f.docs.join("touchHLE_sandbox")).unwrap();assert!(m.begin_game().is_err());let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let a=m.export().unwrap();let p=m.validate(&a).unwrap();let mut directory=f.game().join("tmp");for _ in 0..18{directory=directory.join("nested");}fs::create_dir_all(directory).unwrap();assert!(m.restore(&p.token,true).is_err());assert_eq!(m.state().unwrap()["active"],"legacy");}

#[test]fn UTF8_profile_names_and_XML_metacharacters_round_trip_without_reencoding_payloads(){let f=Fixture::new();f.seed();let name="雪😀<&";let mut index=Vec::from(1u32.to_le_bytes());index.extend_from_slice(&1u16.to_le_bytes());index.extend_from_slice(&(name.len()as u16).to_le_bytes());index.extend_from_slice(name.as_bytes());index.extend_from_slice(&1u32.to_le_bytes());index.extend_from_slice(&1u32.to_le_bytes());let u=f.game().join("Documents/userdata");fs::write(u.join("users.dat"),index).unwrap();fs::remove_file(u.join("user7.dat")).unwrap();let mut pref=plist::Dictionary::new();pref.insert("CurUser".into(),plist::Value::String(name.into()));plist::Value::Dictionary(pref).to_file_xml(f.game().join("Library/Preferences").join(format!("{GAME}.plist"))).unwrap();let mut m=Manager::open(&f.docs).unwrap();let archive=m.export().unwrap();let p=m.validate(&archive).unwrap();assert_eq!(p.profiles,1);m.restore(&p.token,true).unwrap();let guest=m.active_guest(&m.state().unwrap()).unwrap();let p=plist::Value::from_file(guest.join("Library/Preferences").join(format!("{GAME}.plist"))).unwrap();assert_eq!(p.as_dictionary().unwrap()["CurUser"].as_string(),Some(name));assert_eq!(fs::read(guest.join("Documents/userdata/replays/Replay0.peg")).unwrap(),b"owned-opaque-replay");}
#[test]fn malformed_current_profile_preference_is_not_silently_replaced_by_first_profile(){let f=Fixture::new();f.seed();let m=Manager::open(&f.docs).unwrap();for bad in [plist::Value::Integer(1.into()),plist::Value::String("Not indexed".into())]{let mut d=plist::Dictionary::new();d.insert("CurUser".into(),bad);plist::Value::Dictionary(d).to_file_xml(f.game().join("Library/Preferences").join(format!("{GAME}.plist"))).unwrap();assert!(m.export().is_err());}}

#[test]fn cancelling_preview_drops_pending_bytes_and_invalidates_restore_token_without_writes(){let f=Fixture::new();f.seed();let mut m=Manager::open(&f.docs).unwrap();let a=m.export().unwrap();let p=m.validate(&a).unwrap();let before=snapshot(&f.root);assert_eq!(m.pending.len(),1);m.cancel_validation();assert!(m.pending.is_empty());assert!(m.restore(&p.token,true).is_err());assert_eq!(snapshot(&f.root),before);}

#[test]fn dangling_state_preference_and_previous_sandbox_links_fail_closed(){
 let f=Fixture::new();f.seed();let m=Manager::open(&f.docs).unwrap();let state=m.base.join("state.json");symlink(f.root.join("owned-missing-state"),&state).unwrap();assert!(m.state().is_err());fs::remove_file(state).unwrap();let pref=f.game().join("Library/Preferences").join(format!("{GAME}.plist"));fs::remove_file(&pref).unwrap();symlink(f.root.join("owned-missing-pref"),&pref).unwrap();assert!(m.export().is_err());drop(m);
 let f=Fixture::new();let mut m=Manager::open(&f.docs).unwrap();let d=data();let a=f.root.join("owned.zip");archive(&a,&d,Some(&manifest(&d)),&[]);let p=m.validate(&a).unwrap();m.restore(&p.token,true).unwrap();let before=m.state().unwrap();symlink(f.root.join("owned-missing-sandbox"),f.docs.join("touchHLE_sandbox")).unwrap();assert!(m.rollback(true).is_err());assert_eq!(m.state().unwrap(),before);
}
